package net.civeira.phylax.feature.observe.observedalert.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;
import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.observe.observedalertrule.domain.ObservedAlertRuleReference;

class RuleVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property rule of observed alert ")
  void test_rule_v_o_builder() {
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertEquals("10", RuleVO.fromReference("10").getRuleUid(),
        "The builder must store the reference value");
    Assertions.assertEquals("11", RuleVO.tryFromReference("11").getRuleUid(),
        "The builder must store the reference value");
    Assertions.assertEquals("12", RuleVO.tryFromReference("12", fails).getRuleUid(),
        "The builder must store the reference value");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertThrows(ConstraintException.class, () -> RuleVO.tryFrom(null));
    Assertions.assertEquals(ObservedAlertRuleReference.of("one"),
        RuleVO.from(ObservedAlertRuleReference.of("one")).getRule());
    Assertions.assertThrows(ConstraintException.class, () -> RuleVO.tryFrom(new Object() {}));
    Assertions.assertEquals("[" + ObservedAlertRuleReference.of("one") + "]",
        RuleVO.from(ObservedAlertRuleReference.of("one")).toString());
  }
}
